PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS businesses (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), full_name TEXT NOT NULL, email TEXT, phone TEXT, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','employee')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS users_email_unique ON users(email) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS users_phone_unique ON users(phone) WHERE phone IS NOT NULL;
CREATE TABLE IF NOT EXISTS branches (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), name TEXT NOT NULL, address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS branch_members (user_id TEXT NOT NULL REFERENCES users(id), branch_id TEXT NOT NULL REFERENCES branches(id), role TEXT NOT NULL DEFAULT 'employee', active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(user_id, branch_id));
CREATE TABLE IF NOT EXISTS operators (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES branches(id), name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES branches(id), operator_id TEXT REFERENCES operators(id), account_type TEXT NOT NULL CHECK(account_type IN ('cash','electronic')), label TEXT NOT NULL, opening_balance INTEGER NOT NULL DEFAULT 0, current_balance INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), branch_id TEXT NOT NULL REFERENCES branches(id), employee_id TEXT NOT NULL REFERENCES users(id), type TEXT NOT NULL CHECK(type IN ('deposit','withdrawal','transfer_in','transfer_out')), operator_id TEXT REFERENCES operators(id), account_id TEXT REFERENCES accounts(id), amount INTEGER NOT NULL CHECK(amount > 0), commission INTEGER NOT NULL DEFAULT 0, customer_phone TEXT, reference TEXT, counterparty_branch_id TEXT REFERENCES branches(id), linked_transaction_id TEXT, note TEXT, created_at TEXT NOT NULL, synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, voided_at TEXT, voided_by TEXT REFERENCES users(id), client_created_id TEXT UNIQUE);
CREATE INDEX IF NOT EXISTS transactions_branch_date ON transactions(branch_id, created_at);
CREATE INDEX IF NOT EXISTS transactions_employee_date ON transactions(employee_id, created_at);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), branch_id TEXT NOT NULL REFERENCES branches(id), email TEXT, phone TEXT, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, accepted_at TEXT);
CREATE TABLE IF NOT EXISTS daily_closures (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), branch_id TEXT NOT NULL REFERENCES branches(id), employee_id TEXT NOT NULL REFERENCES users(id), business_date TEXT NOT NULL, cash_counted INTEGER NOT NULL, electronic_counts TEXT NOT NULL DEFAULT '{}', notes TEXT, status TEXT NOT NULL CHECK(status IN ('pending_sync','submitted','reviewed')), submitted_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(branch_id,business_date,employee_id));
